package ca.yorku.eecs3311.coursepilot.application.service;
import ca.yorku.eecs3311.coursepilot.application.ai.*; import ca.yorku.eecs3311.coursepilot.application.dto.*; import ca.yorku.eecs3311.coursepilot.domain.model.*; import ca.yorku.eecs3311.coursepilot.domain.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class WrongAnswerExplanationService {private final QuizRepository quizzes;private final LlmClient llm;private final PromptBuilder prompts;private final StructuredResponseParser parser;private final GroundingContextBuilder builder;private final DocumentChunkRepository chunks;public WrongAnswerExplanationService(QuizRepository q,LlmClient l,PromptBuilder p,StructuredResponseParser s,GroundingContextBuilder b,DocumentChunkRepository c){quizzes=q;llm=l;prompts=p;parser=s;builder=b;chunks=c;}
 @Transactional(readOnly=true) public GroundedExplanation explain(Long courseId,Long quizId,Long questionId,String answer){Quiz quiz=quizzes.findOwned(quizId,courseId).orElseThrow(()->new IllegalArgumentException("Quiz was not found for this course."));QuizQuestion q=quiz.getQuestions().stream().filter(x->x.getId().equals(questionId)).findFirst().orElseThrow(()->new IllegalArgumentException("Question was not found for this quiz."));if(!llm.checkAvailability().isAvailable())return new GroundedExplanation("Wrong-answer explanation is currently unavailable. Check AI status and try again.",List.of(),true);List<SearchResult> results=new ArrayList<>();for(QuizSource s:q.getSources()){var c=chunks.findById(s.getChunkId()).orElse(null);if(c!=null)results.add(new SearchResult(c.getDocument().getId(),c.getId(),c.getDocument().getOriginalFilename(),c.getChunkIndex(),c.getContent(),1d,c.getStartPage(),c.getEndPage(),List.of()));}var context=builder.build(results,12000);try{var parsed=parser.parse(llm.generate(prompts.buildWrongAnswerExplanationPrompt(q.getPrompt(),answer,q.getReferenceAnswer(),context.text())).content(),WrongAnswerExplanationLlmResponse.class);Map<String,GroundedSource> map=new LinkedHashMap<>();context.sources().forEach(s->map.put(s.sourceId(),s));if(parsed.explanation()==null||parsed.explanation().isBlank()||parsed.sourceIds().isEmpty()||parsed.sourceIds().stream().anyMatch(id->!map.containsKey(id)))throw new IllegalArgumentException("invalid grounded explanation");return new GroundedExplanation(parsed.explanation(),parsed.sourceIds().stream().map(map::get).toList(),false);}catch(RuntimeException e){return new GroundedExplanation("The explanation could not be validated safely. Review the cited course material and try again.",List.of(),true);}}
}
